import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [, second] = input;
const a = second.split(" ").map(Number);

// 値を 1 始まりの順位に置き換える（座標圧縮）
const sorted = [...new Set(a)].sort((x, y) => x - y);
const rank = new Map<number, number>();
sorted.forEach((v, i) => rank.set(v, i + 1));

// BIT（Fenwick 木）: 順位ごとの出現回数を管理し、前からの和を O(log N) で求める
const m = sorted.length;
const bit = new Int32Array(m + 1);
const add = (i: number) => {
  for (; i <= m; i += i & -i) bit[i]++;
};
const sum = (i: number) => {
  let s = 0;
  for (; i > 0; i -= i & -i) s += bit[i];
  return s;
};

let inversions = 0;
a.forEach((x, j) => {
  const r = rank.get(x)!;
  // これまでの j 個のうち、x より大きいもの = j - (x 以下の個数)
  inversions += j - sum(r);
  add(r);
});
console.log(inversions);
